// Extract InvoiceID from error execution payload when present; set Status=Paused + Notes.
// Prefer the in-workflow Revert Claim branch for Gmail node failures; this stub covers broader failures.
const root = $input.first().json || {};
const exec = root.execution || root;
const last = (exec.lastNodeExecuted || exec.lastNode || '');
let inv = '';
const tryObjs = [root, exec, root.workflowData, root.error, root.node];
for (const o of tryObjs) {
  if (!o || typeof o !== 'object') continue;
  if (o.InvoiceID) { inv = String(o.InvoiceID); break; }
  if (o.invoiceId) { inv = String(o.invoiceId); break; }
}
// Best-effort dig into execution data items
const data = exec.data || root.data;
if (!inv && data && data.main) {
  try {
    const flat = JSON.stringify(data);
    const m = /"InvoiceID"\s*:\s*"([^"]+)"/.exec(flat);
    if (m) inv = m[1];
  } catch (e) { /* ignore */ }
}
const stamp = new Date().toISOString();
const errMsg = String((root.error && (root.error.message || root.error)) || exec.error || 'workflow error').slice(0, 200);
if (!inv) {
  // Nothing to update — surface for operator logs without writing Sheet
  return [{ json: { skipped: true, reason: 'no_InvoiceID', lastNode: last, errMsg, at: stamp } }];
}
const noteAppend = `[${stamp}] SEND_ERROR — Status=Paused (error workflow): ${errMsg}`;
return [{
  json: {
    InvoiceID: inv,
    Status: 'Paused',
    Notes: noteAppend,
    lastNode: last,
  }
}];

// Append error note onto existing Notes for matching InvoiceID.
const pause = $('Extract Invoice + Build Pause').first().json;
const want = String(pause.InvoiceID || '').trim().toLowerCase();
const out = [];
for (const item of items) {
  const row = item.json;
  const id = String(row.InvoiceID || '').trim();
  if (id.toLowerCase() !== want) continue;
  const prev = String(row.Notes || '').trim();
  const notes = prev ? `${prev} | ${pause.Notes}` : pause.Notes;
  out.push({ json: { InvoiceID: id, Status: 'Paused', Notes: notes } });
}
if (!out.length) {
  out.push({ json: { InvoiceID: pause.InvoiceID, Status: 'Paused', Notes: pause.Notes } });
}
return out;
